/* VIRTUAL_THREAD_OPTIMIZED TRANSACTION_OPTIMIZED */

  SELECT NEXTVAL('${format}_asset_asset_id_seq');


INSERT INTO ${format}_asset (asset_id, repository_id, path, kind, component_id, asset_blob_id, last_updated, last_downloaded,
attributes, asset_blob_size)
VALUES (#{asset.assetId}, #{asset.repositoryId}, #{asset.path}, #{asset.kind}, #{asset.componentId}, #{asset.assetBlobId},
#{asset.lastUpdated}, #{asset.lastDownloaded},  #{asset.attributes}, #{asset.assetBlob.blobSize})
ON CONFLICT (repository_id, path) DO NOTHING;


   WHERE component_id = #{asset.componentId};

/* VIRTUAL_THREAD_OPTIMIZED TRANSACTION_OPTIMIZED */
MERGE INTO ${format}_asset USING (VALUES(
  #{asset.repositoryId}, #{asset.path}, #{asset.kind}, #{asset.componentId}, #{asset.assetBlobId},
  #{asset.lastUpdated}, #{asset.lastDownloaded}, #{asset.attributes}, #{asset.assetBlob.blobSize}
)) AS vals(repository_id, path, kind, component_id, asset_blob_id, last_updated, last_downloaded, attributes, asset_blob_size)
ON ${format}_asset.repository_id = vals.repository_id AND ${format}_asset.path = vals.path
WHEN NOT MATCHED THEN INSERT (repository_id, path, kind, component_id, asset_blob_id, last_updated, last_downloaded, attributes, asset_blob_size)
VALUES (vals.repository_id, vals.path, vals.kind, vals.component_id, vals.asset_blob_id, vals.last_updated, vals.last_downloaded, vals.attributes, vals.asset_blob_size);


   WHERE component_id = #{asset.componentId};

