mapper.select:
/* VIRTUAL_THREAD_OPTIMIZED CLEANUP_QUERY */
SELECT asset_id FROM ${format}_asset
    WHERE repository_id = #{repositoryId} AND component_id IS NULL
    AND last_downloaded <= CURRENT_TIMESTAMP - CAST(#{daysAgo} AS INT) * INTERVAL '1' DAY
     LIMIT #{limit};

